    private fun visible(id: String, title: String, description: String, rarity: Rarity, rule: RuleType, target: Double = 1.0, capability: Capability = Capability.NONE) =
        AchievementDefinition(id, title, description, AchievementCategory.VISIBLE, false, rarity, rule, target, capability)

    private fun hidden(id: String, title: String, description: String, rarity: Rarity, rule: RuleType, target: Double = 1.0, capability: Capability = Capability.NONE) =
        AchievementDefinition(id, title, description, AchievementCategory.HIDDEN, true, rarity, rule, target, capability)

    private fun challenge(id: String, title: String, description: String, rarity: Rarity, capability: Capability, ready: Boolean = true): AchievementDefinition {
        require(ready) { "El catálogo público no admite Challenges sin implementar" }
        return AchievementDefinition(id, title, description, AchievementCategory.CHALLENGE, false, rarity, RuleType.CHALLENGE_COMPLETED, 1.0, capability, ChallengeAvailability.READY)
    }

